/**
 * The client's metric vocabulary mirrors the server engine:
 * shared/metric-matrix.json is regenerated by a backend test from
 * app/services/metrics.py, so a measure, unit, valid dimension, permission
 * need, relative period or grain changed on either side fails here. Plus the
 * display helpers: numbers, periods, dimension names, colours, keys.
 */
import { describe, it, expect } from 'vitest';
import matrix from '../../../../shared/metric-matrix.json';
import {
  ARCHIVED_NEEDS,
  archivedNeeds,
  DIMENSION_KINDS,
  dimensionLabel,
  dimensionNeeds,
  DIVISIBLE_MEASURES,
  FALLBACK_PALETTE,
  FAMILIES,
  FAMILY_DIMENSION_NEEDS,
  FAMILY_FILTER_NEEDS,
  FAMILY_LABELS,
  FILTER_KEYS,
  FILTER_LABELS,
  filterNeeds,
  formatMetric,
  GRAINS,
  isDimensionHidden,
  isDivisible,
  isValidDimension,
  MATRIX,
  MEASURE_FILTERS,
  measureFamily,
  measureLabel,
  measureNeeds,
  MEASURES,
  measuresByFamily,
  NEEDS,
  NO_PERCENT_MEASURES,
  normaliseKey,
  takesFilter,
  OTHER_KEY,
  periodLabel,
  queryUnit,
  RELATIVE_PERIODS,
  resolvedPeriodLabel,
  UNIT_LABELS,
  unitWord,
  widgetColor,
} from '../metrics';
import { SKILL_COLOR_SWATCHES } from '../colorSwatches';
import type { DimensionKind, Measure, MeasureFamily } from '@/types';

const sorted = (values: Iterable<string>) => [...values].sort();

type MatrixMeasure = keyof typeof matrix.measures;
const spec = (measure: Measure) => matrix.measures[measure as MatrixMeasure];

describe('metric matrix mirror', () => {
  it('names exactly the server measures, in its order, with their units', () => {
    expect(MEASURES.map((m) => m.key)).toEqual(Object.keys(matrix.measures));
    for (const measure of MEASURES) {
      expect(measure.unit).toBe(spec(measure.key).unit);
    }
  });

  it('labels the measures like the server (MEASURE_LABELS)', () => {
    expect(Object.fromEntries(MEASURES.map((m) => [m.key, m.label]))).toEqual({
      booked_days: 'Booked days',
      booked_weeks: 'Booked weeks',
      booking_count: 'Bookings',
      people_booked: 'People booked',
      project_count: 'Projects',
      project_weeks: 'Project weeks',
      project_volume: 'Project volume',
      phase_count: 'Phases',
      phase_weeks: 'Phase weeks',
      phases_due: 'Phases due',
      phases_overdue: 'Phases overdue',
      capacity_days: 'Capacity (days)',
      available_days: 'Available days',
      utilisation: 'Utilisation',
      people_over_capacity: 'People over capacity',
      equipment_booked_days: 'Equipment booked days',
      equipment_booking_count: 'Equipment bookings',
      equipment_booked: 'Equipment booked',
      equipment_utilisation: 'Equipment utilisation',
    });
  });

  it('spells the server’s measure, dimension, filter and period names (the JSON labels)', () => {
    expect(Object.fromEntries(MEASURES.map((m) => [m.key, m.label]))).toEqual(matrix.measure_labels);
    expect(Object.fromEntries(DIMENSION_KINDS.map((d) => [d.key, d.label]))).toEqual(matrix.dimension_labels);
    expect(DIMENSION_KINDS.map((d) => d.key)).toEqual(Object.keys(matrix.dimension_labels));
    expect(FILTER_LABELS).toEqual(matrix.filter_labels);
    expect(Object.keys(FILTER_LABELS)).toEqual([...FILTER_KEYS]);
    expect(Object.fromEntries(RELATIVE_PERIODS.map((p) => [p.key, p.label]))).toEqual(matrix.period_labels);
  });

  it('keeps each family contiguous, in the server family order', () => {
    const runs = MEASURES.map((m) => m.family).filter((family, i, all) => i === 0 || all[i - 1] !== family);
    expect(runs).toEqual([...FAMILIES]);
    expect(FAMILIES).toEqual(['booking', 'project', 'phase', 'capacity', 'equipment']);
  });

  it('puts each measure in the family the server’s needs and filters describe', () => {
    for (const [measure, s] of Object.entries(matrix.measures)) {
      const filters: string[] = s.filters;
      let family: MeasureFamily;
      if (s.needs === 'views.staff') family = 'capacity';
      else if (s.needs === 'views.equipment') family = 'equipment';
      else if (filters.includes('milestones')) family = 'phase';
      else if (filters.includes('person_ids')) family = 'booking';
      else family = 'project';
      expect([measure, measureFamily(measure as Measure)]).toEqual([measure, family]);
    }
  });

  it('accepts the same dimensions per measure', () => {
    for (const [measure, s] of Object.entries(matrix.measures)) {
      expect(sorted(MATRIX[measure as Measure])).toEqual(sorted(s.dimensions));
      expect(new Set(MATRIX[measure as Measure]).size).toBe(MATRIX[measure as Measure].length);
    }
  });

  it('takes the same filters per measure', () => {
    for (const [measure, s] of Object.entries(matrix.measures)) {
      expect([measure, sorted(MEASURE_FILTERS[measure as Measure])]).toEqual([measure, sorted(s.filters)]);
      expect(new Set(MEASURE_FILTERS[measure as Measure]).size).toBe(MEASURE_FILTERS[measure as Measure].length);
    }
  });

  it('names every dimension kind the matrix uses, and every filter key', () => {
    const used = new Set(Object.values(matrix.measures).flatMap((m) => m.dimensions));
    expect(sorted(DIMENSION_KINDS.map((d) => d.key))).toEqual(sorted(used));
    const filters = new Set(Object.values(matrix.measures).flatMap((m) => m.filters));
    expect(sorted(FILTER_KEYS)).toEqual(sorted(filters));
  });

  it('asks for the same permissions: per measure, and the merged dimension / filter / archived map', () => {
    for (const [measure, s] of Object.entries(matrix.measures)) {
      expect([measure, measureNeeds(measure as Measure)]).toEqual([measure, s.needs]);
    }
    expect(NEEDS).toEqual(matrix.needs);
    expect(ARCHIVED_NEEDS).toBe(matrix.needs.archived);
    for (const { key } of DIMENSION_KINDS) {
      expect([key, dimensionNeeds(key)]).toEqual([key, (matrix.needs as Record<string, string>)[key] ?? null]);
    }
    for (const key of FILTER_KEYS) {
      const expected = key === 'archived' ? null : (matrix.needs as Record<string, string>)[key] ?? null;
      expect([key, filterNeeds(key)]).toEqual([key, expected]);
    }
  });

  it('asks for the same family-specific keys per measure (capacity by person: absences.view_others)', () => {
    for (const [measure, s] of Object.entries(matrix.measures)) {
      const family = measureFamily(measure as Measure);
      expect([measure, FAMILY_DIMENSION_NEEDS[family] ?? {}]).toEqual([measure, s.dimension_needs]);
      expect([measure, FAMILY_FILTER_NEEDS[family] ?? {}]).toEqual([measure, s.filter_needs]);
      const dims = s.dimension_needs as Record<string, string>;
      const flts = s.filter_needs as Record<string, string>;
      const common = matrix.needs as Record<string, string>;
      for (const { key } of DIMENSION_KINDS) {
        const expected = dims[key] ?? common[key] ?? null;
        expect([measure, key, dimensionNeeds(key, measure as Measure)]).toEqual([measure, key, expected]);
      }
      for (const key of FILTER_KEYS) {
        const expected = key === 'archived' ? null : flts[key] ?? common[key] ?? null;
        expect([measure, key, filterNeeds(key, measure as Measure)]).toEqual([measure, key, expected]);
      }
    }
    expect(dimensionNeeds('person', 'utilisation')).toBe('absences.view_others');
    expect(dimensionNeeds('team', 'utilisation')).toBeNull();
    expect(dimensionNeeds('person', 'booked_days')).toBe('views.staff');
    expect(dimensionNeeds('person')).toBe('views.staff');
    expect(filterNeeds('person_ids', 'capacity_days')).toBe('absences.view_others');
    expect(filterNeeds('person_ids')).toBe('views.staff');
  });

  it('refuses a percentage on the same measures', () => {
    expect(sorted(NO_PERCENT_MEASURES)).toEqual(matrix.no_percent);
  });

  it('divides the same measures in a calculated widget', () => {
    expect(sorted(DIVISIBLE_MEASURES)).toEqual(matrix.divisible);
    expect(isDivisible('booked_days')).toBe(true);
    expect(isDivisible('utilisation')).toBe(false);
  });

  it('offers the same relative periods and grains, in order', () => {
    expect(RELATIVE_PERIODS.map((p) => p.key)).toEqual(matrix.relative_periods);
    expect(GRAINS.map((g) => g.key)).toEqual(matrix.grains);
  });
});

describe('matrix helpers', () => {
  it('tells valid dimensions apart', () => {
    expect(isValidDimension('booked_weeks', 'person')).toBe(true);
    expect(isValidDimension('people_booked', 'period')).toBe(false);
    expect(isValidDimension('project_volume', 'period')).toBe(false);
    expect(isValidDimension('phase_count', 'phase_type')).toBe(true);
    expect(isValidDimension('phases_due', 'status')).toBe(true);
    expect(isValidDimension('booked_days', 'status')).toBe(false);
    expect(isValidDimension('project_count', 'team')).toBe(false);
    expect(isValidDimension('utilisation', 'project')).toBe(false);
    expect(isValidDimension('equipment_utilisation', 'equipment_type')).toBe(true);
    expect(isValidDimension('booked_days', 'equipment')).toBe(false);
    expect(isValidDimension('unknown' as Measure, 'site')).toBe(false);
  });

  it('tells the filters a measure takes', () => {
    expect(takesFilter('booked_days', 'person_ids')).toBe(true);
    // Utilisation's booked side takes the project filters, not the other capacity measures.
    expect(takesFilter('utilisation', 'project_ids')).toBe(true);
    expect(takesFilter('utilisation', 'has_customer')).toBe(true);
    expect(takesFilter('available_days', 'project_ids')).toBe(false);
    expect(takesFilter('people_over_capacity', 'has_customer')).toBe(false);
    expect(takesFilter('project_count', 'has_customer')).toBe(true);
    expect(takesFilter('equipment_utilisation', 'has_customer')).toBe(false);
    expect(takesFilter('phase_count', 'milestones')).toBe(true);
    expect(takesFilter('equipment_utilisation', 'equipment_types')).toBe(true);
    expect(takesFilter('unknown' as Measure, 'site_ids')).toBe(false);
  });

  it('knows each measure’s family and name, unknown ones too', () => {
    expect(measureFamily('utilisation')).toBe('capacity');
    expect(measureFamily('unknown' as Measure)).toBe('booking');
    expect(measureLabel('phases_due')).toBe('Phases due');
    expect(measureLabel('unknown' as Measure)).toBe('unknown');
  });

  it('groups the measures by family for the picker, empty families dropped', () => {
    const groups = measuresByFamily();
    expect(groups.map((g) => g.label)).toEqual(['Bookings', 'Projects', 'Phases', 'Capacity', 'Equipment']);
    expect(groups.flatMap((g) => g.options.map((o) => o.value))).toEqual(MEASURES.map((m) => m.key));
    expect(groups[3].options).toEqual([
      { value: 'capacity_days', label: 'Capacity (days)' },
      { value: 'available_days', label: 'Available days' },
      { value: 'utilisation', label: 'Utilisation' },
      { value: 'people_over_capacity', label: 'People over capacity' },
    ]);
    const noCapacity = measuresByFamily((m) => measureFamily(m) !== 'capacity');
    expect(noCapacity.map((g) => g.label)).toEqual(['Bookings', 'Projects', 'Phases', 'Equipment']);
    expect(FAMILY_LABELS.equipment).toBe('Equipment');
  });

  it('needs views.archived only to include archived projects', () => {
    expect(archivedNeeds(undefined)).toBeNull();
    expect(archivedNeeds('exclude')).toBeNull();
    expect(archivedNeeds('include')).toBe('views.archived');
    expect(archivedNeeds('only')).toBe('views.archived');
  });

  it('labels the relative periods', () => {
    expect(RELATIVE_PERIODS.map((p) => p.label)).toEqual([
      'This year',
      'Last year',
      'Next year',
      'This quarter',
      'Last quarter',
      'Next quarter',
      'This month',
      'Last month',
      'Next month',
      'Last 12 months',
      'Next 12 months',
      'All time',
    ]);
  });

  it('derives a query’s unit from its measure, or percent', () => {
    expect(queryUnit({ measure: 'booked_weeks' })).toBe('weeks');
    expect(queryUnit({ measure: 'project_count', percent_of: 'total' })).toBe('percent');
    expect(queryUnit({ measure: 'utilisation' })).toBe('percent');
    expect(queryUnit({ measure: 'equipment_booked' })).toBe('equipment');
    expect(queryUnit({ measure: 'unknown' as Measure })).toBe('count');
    expect(queryUnit({ measure: 'booked_days', divide_by: { measure: 'capacity_days' } })).toBe('percent');
    expect(queryUnit({ measure: 'booked_days', divide_by: { measure: 'capacity_days', result: 'number' } })).toBe('number');
  });
});

describe('formatMetric', () => {
  it('shows weeks and days with one decimal', () => {
    expect(formatMetric(12, 'weeks')).toBe('12.0');
    expect(formatMetric(3.456, 'days')).toBe('3.5');
    expect(formatMetric(1234.5, 'weeks')).toBe('1,234.5');
  });

  it('shows counts as integers', () => {
    expect(formatMetric(7, 'projects')).toBe('7');
    expect(formatMetric(7.6, 'count')).toBe('8');
    expect(formatMetric(3, 'people')).toBe('3');
    expect(formatMetric(2, 'phases')).toBe('2');
    expect(formatMetric(4, 'equipment')).toBe('4');
  });

  it('shows volumes with up to two decimals', () => {
    expect(formatMetric(1500, 'volume')).toBe('1,500');
    expect(formatMetric(12.345, 'volume')).toBe('12.35');
  });

  it('shows percentages with a thin space before %', () => {
    expect(formatMetric(12.5, 'percent')).toBe('12.5 %');
    expect(formatMetric(50, 'percent')).toBe('50 %');
  });

  it('shows a percentage past 100 as it is, never clamped (a double booking)', () => {
    expect(formatMetric(110, 'percent')).toMatch(/^110\s%$/);
    expect(formatMetric(254.55, 'percent')).toMatch(/^254\.6\s%$/);
  });

  it('follows number_format', () => {
    expect(formatMetric(12.34, 'weeks', { number_format: 'integer' })).toBe('12');
    expect(formatMetric(3, 'projects', { number_format: 'decimal' })).toBe('3.00');
    expect(formatMetric(12.5, 'weeks', { number_format: 'percent' })).toBe('12.5 %');
    expect(formatMetric(12.5, 'percent', { number_format: 'integer' })).toBe('13 %');
    expect(formatMetric(12.5, 'weeks', null)).toBe('12.5');
  });

  it('shows a calculated plain number with two decimals and no unit word', () => {
    expect(formatMetric(0.4545, 'number')).toBe('0.45');
    expect(formatMetric(2, 'number')).toBe('2.00');
    expect(unitWord(1, 'number')).toBe('');
  });

  it('shows a dash for no value', () => {
    expect(formatMetric(null, 'weeks')).toBe('–');
    expect(formatMetric(null, 'percent')).toBe('–');
    expect(formatMetric(undefined, 'weeks')).toBe('–');
    expect(formatMetric(Number.NaN, 'weeks')).toBe('–');
  });
});

describe('unitWord', () => {
  it('is singular when the value reads exactly 1, plural otherwise', () => {
    expect(unitWord(1, 'phases')).toBe('phase');
    expect(unitWord(1, 'people')).toBe('person');
    expect(unitWord(1, 'projects')).toBe('project');
    expect(unitWord(1, 'count')).toBe('booking');
    expect(unitWord(1, 'equipment')).toBe('equipment');
    expect(unitWord(1, 'volume')).toBe('volume');
    expect(unitWord(0, 'phases')).toBe('phases');
    expect(unitWord(2, 'people')).toBe('people');
    expect(unitWord(1.4, 'people')).toBe('person'); // displayed as "1"
    expect(unitWord(null, 'people')).toBe('people');
    expect(unitWord(-1, 'phases')).toBe('phases');
    // Days and weeks show a decimal: "1.0 days"; as integers, "1 day".
    expect(unitWord(1, 'days')).toBe('days');
    expect(unitWord(1, 'days', { number_format: 'integer' })).toBe('day');
    expect(unitWord(1.2, 'weeks', { number_format: 'integer' })).toBe('week');
    expect(unitWord(1, 'phases', { number_format: 'decimal' })).toBe('phases');
    expect(unitWord(1, 'percent')).toBe('');
  });
});

describe('labels', () => {
  it('names a period: relative by its label, absolute by its dates', () => {
    expect(periodLabel({ relative: 'last_12_months' })).toBe('Last 12 months');
    expect(periodLabel(undefined)).toBe('This year');
    expect(periodLabel({ relative: 'someday' as never })).toBe('someday');
    expect(periodLabel({ from: '2026-01-01', to: '2026-12-31' })).toBe(
      resolvedPeriodLabel({ from: '2026-01-01', to: '2026-12-31' })
    );
    expect(resolvedPeriodLabel({ from: '2026-01-01', to: '2026-12-31' })).toMatch(/2026 – .*2026$/);
  });

  it('names dimensions: fields by name, built-ins by their instance label, periods by grain', () => {
    const fields = [{ id: 3, name: 'Project type' }];
    const settings = { project_field_labels: '{"customer":"Client","confirmed":"Signed"}' };
    expect(dimensionLabel({ kind: 'field', field_id: 3 }, fields, settings)).toBe('Project type');
    expect(dimensionLabel({ kind: 'field', field_id: 9 }, fields, settings)).toBe('Project field');
    expect(dimensionLabel({ kind: 'customer' }, fields, settings)).toBe('Client');
    expect(dimensionLabel({ kind: 'confirmed' }, fields, settings)).toBe('Signed');
    expect(dimensionLabel({ kind: 'customer' }, fields, null)).toBe('Customer');
    expect(dimensionLabel({ kind: 'period', grain: 'month' }, fields, null)).toBe('Month');
    expect(dimensionLabel({ kind: 'period', grain: 'decade' as never }, fields, null)).toBe('Period');
    expect(dimensionLabel({ kind: 'project_manager' }, fields, null)).toBe('Project manager');
    expect(dimensionLabel({ kind: 'status' }, fields, null)).toBe('Status');
    expect(dimensionLabel({ kind: 'equipment' }, fields, null)).toBe('Equipment');
    expect(dimensionLabel({ kind: 'equipment_type' }, fields, null)).toBe('Equipment type');
    expect(dimensionLabel({ kind: 'mystery' as Exclude<DimensionKind, 'field' | 'period'> }, fields, null)).toBe(
      'mystery'
    );
  });

  it('hides the Customer dimension while the built-in field is hidden', () => {
    expect(isDimensionHidden('customer', { project_fields_hidden: '["customer"]' })).toBe(true);
    expect(isDimensionHidden('customer', null)).toBe(false);
    expect(isDimensionHidden('confirmed', { project_fields_hidden: '["customer"]' })).toBe(false);
  });

  it('has a word for every unit but percent', () => {
    expect(UNIT_LABELS.weeks).toBe('weeks');
    expect(UNIT_LABELS.count).toBe('bookings');
    expect(UNIT_LABELS.equipment).toBe('equipment');
    expect(UNIT_LABELS.percent).toBe('');
  });
});

describe('widgetColor', () => {
  it('takes the value’s own colour first', () => {
    expect(widgetColor({ key: 4, label: 'Team A', color: '#123456' }, 0, ['a'])).toBe('#123456');
  });

  it('falls back to the palette by position, wrapping', () => {
    expect(widgetColor({ key: 4, label: 'X' }, 0, ['a', 'b'])).toBe('a');
    expect(widgetColor({ key: 5, label: 'Y' }, 3, ['a', 'b'])).toBe('b');
    expect(widgetColor(null, 1)).toBe(FALLBACK_PALETTE[1]);
    expect(widgetColor(null, 0, [])).toBe(FALLBACK_PALETTE[0]);
    expect(FALLBACK_PALETTE).toEqual(SKILL_COLOR_SWATCHES.map((s) => s.value));
  });

  it('gives "Other" its own colour when asked', () => {
    expect(widgetColor({ key: OTHER_KEY, label: 'Other' }, 2, ['a', 'b', 'c'], 'grey')).toBe('grey');
    expect(widgetColor({ key: OTHER_KEY, label: 'Other' }, 2, ['a', 'b', 'c'])).toBe('c');
  });
});

describe('normaliseKey', () => {
  it('compares numbers, booleans and texts in one form', () => {
    expect(normaliseKey('3')).toBe(3);
    expect(normaliseKey(3)).toBe(3);
    expect(normaliseKey('2.5')).toBe(2.5);
    expect(normaliseKey('true')).toBe(true);
    expect(normaliseKey('false')).toBe(false);
    expect(normaliseKey(true)).toBe(true);
    expect(normaliseKey('Acme')).toBe('Acme');
    expect(normaliseKey('2026-Q1')).toBe('2026-Q1');
    expect(normaliseKey(null)).toBeNull();
    expect(normaliseKey(undefined)).toBeNull();
  });
});
